// 普通树：A 的孩子是 B、C；B 的孩子是 D
typedef struct Node {
    char data;                 // 如 'A'
    struct Node* firstChild;   // 最左孩子
    struct Node* nextSibling;  // 右兄弟
} Node;

Node A = {'A', &B, NULL};
Node B = {'B', &D, &C};
Node C = {'C', NULL, NULL};
Node D = {'D', NULL, NULL};

