// 链式表示：每个节点保存值与子节点指针
struct Node {
    int val;
    vector<Node*> children;   // 普通树：任意多个子节点
};

// 顺序表示：完全二叉树用数组存储，下标从 0 开始
// 例：数组 [A, B, C, D, E, F, G] 中，节点 4 的父节点是 (4-1)/2 = 1
//     节点 1 的左孩子是 2*1+1 = 3，右孩子是 2*1+2 = 4
int parent(int i) { return (i - 1) / 2; }
int left  (int i) { return 2 * i + 1; }
int right (int i) { return 2 * i + 2; }
